    private fun checkMesh(
        progress: Double,
        grab: Double,
        move: Double,
        back: Boolean,
        folded: Boolean,
        expectedSize: Int,
        indices: IntArray,
        expected: DoubleArray,
    ) {
        val actual = PhysicalPageMesh.create(progress, grab, move, back, folded)
        assertEquals(expectedSize, actual.size)
        indices.forEachIndexed { i, position ->
            assertEquals(expected[i], actual[position].toDouble(), 0.000002, "v4.0 vertex at $position")
        }
    }
